// Advanced Weekly Business Insights Calculator for {{CLINIC_NAME}}
const now = new Date();
const timezone = '{{TIMEZONE}}';
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const monthAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);

console.log(`📊 Generating weekly insights for {{CLINIC_NAME}} - ${now.toLocaleDateString()}`);

// Get data from all sources
const payments = $items('💰 Get Payments Data').map(item => item.json).filter(p => p && p.Date);
const clients = $items('👥 Get Clients Data').map(item => item.json).filter(c => c && c['Join Date']);
const appointments = $items('📅 Get Appointments Data').map(item => item.json).filter(a => a && a.Date);

console.log(`📋 Data loaded: ${payments.length} payments, ${clients.length} clients, ${appointments.length} appointments`);

// Helper function to parse dates safely
function parseDate(dateStr) {
  try {
    if (!dateStr) return null;
    const date = new Date(dateStr);
    return isNaN(date.getTime()) ? null : date;
  } catch (error) {
    return null;
  }
}

// Helper function to parse currency amounts
function parseAmount(amountStr) {
  if (!amountStr) return 0;
  const cleaned = amountStr.toString().replace(/[^0-9.-]/g, '');
  const amount = parseFloat(cleaned);
  return isNaN(amount) ? 0 : amount;
}

// Calculate Weekly Metrics
const weeklyPayments = payments.filter(p => {
  const paymentDate = parseDate(p.Date || p['Payment Date'] || p['Date Paid']);
  return paymentDate && paymentDate >= weekAgo;
});

const weeklyRevenue = weeklyPayments.reduce((sum, payment) => {
  const amount = parseAmount(payment.Amount || payment.Total || payment.Revenue || 0);
  return sum + amount;
}, 0);

const weeklyAppointments = appointments.filter(a => {
  const appointmentDate = parseDate(a.Date || a['Appointment Date']);
  return appointmentDate && appointmentDate >= weekAgo;
});

const newClientsThisWeek = clients.filter(c => {
  const joinDate = parseDate(c['Join Date'] || c.JoinDate || c['Registration Date']);
  return joinDate && joinDate >= weekAgo;
});

// Calculate Monthly Comparisons
const monthlyPayments = payments.filter(p => {
  const paymentDate = parseDate(p.Date || p['Payment Date'] || p['Date Paid']);
  return paymentDate && paymentDate >= monthAgo;
});

const monthlyRevenue = monthlyPayments.reduce((sum, payment) => {
  const amount = parseAmount(payment.Amount || payment.Total || payment.Revenue || 0);
  return sum + amount;
}, 0);

const monthlyAppointments = appointments.filter(a => {
  const appointmentDate = parseDate(a.Date || a['Appointment Date']);
  return appointmentDate && appointmentDate >= monthAgo;
});

const newClientsThisMonth = clients.filter(c => {
  const joinDate = parseDate(c['Join Date'] || c.JoinDate || c['Registration Date']);
  return joinDate && joinDate >= monthAgo;
});

// Calculate Service Breakdown (this week)
const serviceBreakdown = {};
weeklyAppointments.forEach(appointment => {
  const service = appointment.Service || appointment['Service Type'] || 'General Visit';
  serviceBreakdown[service] = (serviceBreakdown[service] || 0) + 1;
});

const topServices = Object.entries(serviceBreakdown)
  .sort(([,a], [,b]) => b - a)
  .slice(0, 5)
  .map(([service, count]) => `  • ${service}: ${count} appointments`)
  .join('\n');

// Calculate Average Transaction Value
const avgTransactionValue = weeklyPayments.length > 0 
  ? (weeklyRevenue / weeklyPayments.length)
  : 0;

// Calculate Growth Rates
const revenueGrowthRate = monthlyRevenue > 0 
  ? ((weeklyRevenue * 4.33 - monthlyRevenue) / monthlyRevenue * 100)
  : 0;

const appointmentGrowthRate = monthlyAppointments.length > 0 
  ? ((weeklyAppointments.length * 4.33 - monthlyAppointments.length) / monthlyAppointments.length * 100)
  : 0;

// Identify Top Paying Clients (this week)
const clientPayments = {};
weeklyPayments.forEach(payment => {
  const clientName = payment['Client Name'] || payment.Client || payment['Customer Name'] || 'Unknown';
  const amount = parseAmount(payment.Amount || payment.Total || payment.Revenue || 0);
  clientPayments[clientName] = (clientPayments[clientName] || 0) + amount;
});

const topPayingClients = Object.entries(clientPayments)
  .sort(([,a], [,b]) => b - a)
  .slice(0, 3)
  .map(([client, amount]) => `  • ${client}: $${amount.toFixed(2)}`)
  .join('\n');

// Generate Insights and Recommendations
const insights = [];

if (weeklyRevenue > monthlyRevenue / 4) {
  insights.push('📈 Revenue is above monthly average - great performance!');
} else {
  insights.push('📉 Revenue is below monthly average - consider promotional activities.');
}

if (newClientsThisWeek.length > 0) {
  insights.push(`🆕 ${newClientsThisWeek.length} new clients joined - retention focus recommended.`);
}

if (weeklyAppointments.length > monthlyAppointments.length / 4) {
  insights.push('📅 Appointment volume is strong this week.');
} else {
  insights.push('📅 Appointment volume is lower - consider outreach campaigns.');
}

// Compile the comprehensive report
const reportData = {
  clinic_name: '{{CLINIC_NAME}}',
  report_date: now.toLocaleDateString('en-US', { 
    weekday: 'long', 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric',
    timeZone: timezone
  }),
  week_ending: now.toLocaleDateString('en-US', { timeZone: timezone }),

  // Weekly Metrics
  weekly_revenue: weeklyRevenue,
  weekly_appointments: weeklyAppointments.length,
  weekly_new_clients: newClientsThisWeek.length,
  weekly_transactions: weeklyPayments.length,
  avg_transaction_value: avgTransactionValue,

  // Monthly Context
  monthly_revenue: monthlyRevenue,
  monthly_appointments: monthlyAppointments.length,
  monthly_new_clients: newClientsThisMonth.length,

  // Growth Metrics
  revenue_growth_rate: revenueGrowthRate,
  appointment_growth_rate: appointmentGrowthRate,

  // Service Analysis
  top_services: topServices || 'No appointments recorded',
  total_services_offered: Object.keys(serviceBreakdown).length,

  // Client Analysis
  top_paying_clients: topPayingClients || 'No payments recorded',
  total_active_clients: clients.length,

  // AI Insights
  business_insights: insights.join('\n'),

  // Report Quality Indicators
  data_completeness: {
    payments: payments.length,
    clients: clients.length,
    appointments: appointments.length
  }
};

console.log(`✅ Weekly insights calculated: $${weeklyRevenue.toFixed(2)} revenue, ${weeklyAppointments.length} appointments, ${newClientsThisWeek.length} new clients`);

return [{ json: reportData }];
